# Roe - The Nursing Assistant (Goodheart-Willcox).
# HOSA lists this book as "The Nursing Assistant: Essentials of Holistic Care". Chapter list: the current
# 2nd edition, published as "The Nursing Assistant: Foundations of Holistic Caregiving" (2027), from the
# publisher's table of contents (g-w.com). Summaries are written for this site, not copied from the book.

def ch(n, title, text, keys):
    return (n, title, [text], keys)

C = [
    ch(1, "The Holistic Nursing Assistant", "Nursing assistants provide basic care under the supervision of a licensed nurse. Holistic care treats the whole person—body, mind, and spirit. NAs must complete state-approved training (at least 75 hours under federal law) and pass a competency exam to be listed on the state registry.", ["Work under nurse supervision", "Holistic = whole person", "75-hour minimum training", "State registry"]),
    ch(2, "Healthcare Facilities and Environments", "Settings include hospitals (acute care), long-term care facilities, assisted living, home health, hospice, and rehabilitation centers. The health care team includes nurses, physicians, therapists, and others. Facilities follow a chain of command.", ["Acute vs. long-term care", "Health care team", "Chain of command", "Many settings"]),
    ch(3, "Holistic Practice", "Holistic care respects each resident's physical, emotional, social, cultural, and spiritual needs. Person-centered care puts the resident's preferences first. Complementary therapies may be part of care.", ["Person-centered care", "Respect preferences", "Cultural and spiritual needs", "Whole-person approach"]),
    ch(4, "Legal and Ethical Practice", "Residents have rights under OBRA, including privacy, dignity, and freedom from abuse and restraints. NAs must keep information confidential (HIPAA), stay within scope of practice, and report abuse or neglect. Negligence and malpractice are legal risks.", ["Residents' rights (OBRA)", "HIPAA confidentiality", "Report abuse", "Scope of practice"]),
    ch(5, "Safe Practice", "Safety includes preventing falls (call light within reach, bed low, nonskid footwear), using proper body mechanics, fire safety (RACE and PASS), and avoiding restraints. Identify residents before care.", ["Call light in reach", "RACE and PASS", "Body mechanics", "Restraint alternatives"]),
    ch(6, "Infection Prevention and Control", "The chain of infection links agent, reservoir, portal of exit, mode of transmission, portal of entry, and susceptible host. Hand hygiene is the most important measure. Standard precautions and transmission-based precautions use PPE appropriately.", ["Chain of infection", "Hand hygiene", "Standard precautions", "PPE"]),
    ch(7, "Human Behavior, Needs, and Health and Wellness", "Maslow's hierarchy of needs places physical needs first, then safety, love and belonging, esteem, and self-actualization. Growth and development continue through the life span. Defense mechanisms and coping affect behavior.", ["Maslow's hierarchy", "Physical needs first", "Life span development", "Coping"]),
    ch(8, "The Body's Anatomy and Physiology", "NAs need basic knowledge of body systems—integumentary, musculoskeletal, nervous, cardiovascular, respiratory, digestive, urinary, endocrine, reproductive, and immune—and how aging affects them.", ["Body systems", "Aging changes", "Normal function", "Report changes"]),
    ch(9, "Diseases, Conditions, and Pain", "Common conditions include diabetes, heart disease, stroke, COPD, arthritis, and cancer. Pain is subjective; NAs observe and report signs of pain and use comfort measures.", ["Common chronic diseases", "Pain is subjective", "Observe and report", "Comfort measures"]),
    ch(10, "Communication, Caring, and Appreciating Differences", "Effective communication uses active listening, clear language, and nonverbal cues. Adapt for hearing or vision loss and cognitive impairment. Cultural humility helps respect differences.", ["Active listening", "Nonverbal communication", "Adapt for impairments", "Cultural humility"]),
    ch(11, "Planning, Observing, and Documenting Care", "The nursing process guides care. NAs make objective (signs) and subjective (symptoms) observations, report changes promptly, and document accurately. 'If it wasn't documented, it wasn't done.'", ["Objective vs. subjective", "Report changes", "Accurate documentation", "Care plan"]),
    ch(12, "Vital Signs, Height, and Weight", "Vital signs: temperature (oral normal ~98.6°F), pulse (60–100), respirations (12–20), blood pressure (normal under 120/80), and pain. Weigh residents at the same time, with the same scale and clothing.", ["Pulse 60–100", "Respirations 12–20", "BP < 120/80", "Consistent weighing"]),
    ch(13, "Mathematics for Holistic Nursing Assistants", "NAs use math for intake and output (1 oz = 30 mL), military (24-hour) time, conversions, and measuring. Accuracy is essential.", ["1 oz = 30 mL", "24-hour time", "Intake and output", "Conversions"]),
    ch(14, "Physical Examination and Specimen Collection", "NAs assist with exams by positioning and draping. They collect specimens such as clean-catch urine, stool, and sputum (best collected in the morning), labeling them correctly.", ["Positioning and draping", "Clean-catch urine", "Sputum in the morning", "Label specimens"]),
    ch(15, "Restful Environment", "A restful environment includes a clean, comfortable unit, proper bedmaking (occupied and unoccupied), comfortable temperature, and reduced noise. Sleep is essential for health.", ["Bedmaking", "Comfortable unit", "Reduce noise", "Promote sleep"]),
    ch(16, "Personal Hygiene", "Hygiene care includes bathing, oral care (including for unconscious residents and dentures), perineal care (front to back), shaving, hair and nail care, and dressing (weak side first). Check skin for pressure injuries.", ["Perineal care front to back", "Dress weak side first", "Oral care", "Check skin"]),
    ch(17, "Mobility", "Mobility care includes repositioning every 2 hours, range-of-motion exercises, transfers with a gait belt, ambulation with assistive devices, and preventing complications of immobility like pressure injuries and contractures.", ["Reposition every 2 hours", "Gait belt", "ROM exercises", "Prevent contractures"]),
    ch(18, "Healthy Eating and Nutritional Challenges", "NAs serve meals, assist with feeding (sit at eye level, small bites), follow therapeutic diets, and watch for dysphagia (swallowing problems) and aspiration. Record meal percentages.", ["Therapeutic diets", "Dysphagia precautions", "Upright for meals", "Record intake"]),
    ch(19, "Hydration and Elimination", "NAs encourage fluids, measure intake and output, assist with toileting, bedpans, and urinals, provide catheter care (keep bag below the bladder), and report changes in urine or stool.", ["Encourage fluids", "Measure I&O", "Catheter bag below bladder", "Report changes"]),
    ch(20, "Mental and Emotional Health, Disabilities, and Cognitive Disorders", "NAs care for residents with depression, anxiety, intellectual and developmental disabilities, and dementia including Alzheimer's disease. Use calm, simple communication and validation; avoid arguing.", ["Dementia care", "Validation", "Simple communication", "Don't argue"]),
    ch(21, "Special Populations—Mothers, Infants, and Surgery", "NAs may care for new mothers (watch for bleeding), newborns (safe sleep on back), and surgical patients (preoperative preparation and postoperative care such as deep breathing and preventing blood clots).", ["Postpartum bleeding", "Newborn safe sleep", "Post-op deep breathing", "Prevent blood clots"]),
    ch(22, "Emergencies and Disasters", "NAs respond to emergencies such as choking (abdominal thrusts), cardiac arrest (CPR), falls, seizures (protect from injury, don't restrain), and disasters following facility plans.", ["Choking: abdominal thrusts", "CPR", "Seizures: protect, don't restrain", "Disaster plans"]),
    ch(23, "End-of-Life Care", "End-of-life care provides comfort and dignity through hospice and palliative care. Respect advance directives and DNR orders. Postmortem care treats the body with respect. Kübler-Ross's grief stages describe common reactions.", ["Hospice and palliative care", "Advance directives", "Postmortem care", "Grief stages"]),
    ch(24, "Certification, Employment, the Workplace, and Lifelong Learning", "NAs pass a state competency exam (written and skills) to be certified and listed on the registry. Job seeking includes résumés and interviews. Professionalism, continuing education (12 hours yearly under federal rules), and teamwork support career growth.", ["Competency exam", "State registry", "12 hours CE per year", "Professionalism"]),
]

